-- 00_setup.sql: catalog and schemas for the Werkbank x Databricks MCP demo.
-- All data is synthetic. Run the files in numeric order, or paste all-in-one.sql.
--
-- If you may not create a catalog in your metastore, create one in the UI (or pick one you own) and
-- load with another name: see "Using another catalog" in the README. Do not edit this file by hand for that.

CREATE CATALOG IF NOT EXISTS werkbank_demo
  COMMENT 'Synthetic data for the Werkbank x Databricks MCP demo. Fictional vendors, customers and numbers.';

CREATE SCHEMA IF NOT EXISTS werkbank_demo.fin
  COMMENT 'Finance: gross margin against plan by region and product line (demo scenario 1).';

CREATE SCHEMA IF NOT EXISTS werkbank_demo.ops
  COMMENT 'Pipeline operations: job runs, lineage and downstream assets (demo scenario 2).';

CREATE SCHEMA IF NOT EXISTS werkbank_demo.scm
  COMMENT 'Supply chain: purchase orders, vendors and delivery-delay risk (demo scenario 3).';
